-- Gvirgvina Mountain Trail (OSM relation 15913873)
INSERT INTO trails (id, name_en, name_ka, description_en, description_ka, difficulty, region, distance_km, elevation_gain_m, estimated_hours, start_address, elevation_profile, review_flags, route, start_point, end_point, is_published) VALUES (
  'a0000000-0000-0000-0000-000000000034', 'Gvirgvina Mountain Trail', 'გვირგვინას მთის ბილიკი',
  'A 25.7 km route. Total ascent about 663 m and descent about 1,864 m; the highest point is about 2,266 m above sea level. Along the way: Gvirgvina.',
