-- Tsvirmi - Zuruldi Ski Lift - Heshkili - Lemsia (OSM relation 13095214)
INSERT INTO trails (id, name_en, name_ka, description_en, description_ka, difficulty, region, distance_km, elevation_gain_m, estimated_hours, start_address, elevation_profile, review_flags, route, start_point, end_point, is_published) VALUES (
  'a0000000-0000-0000-0000-000000000145', 'Tsvirmi - Zuruldi Ski Lift - Heshkili - Lemsia', '',
  'A 17.6 km route from Tsvirmi to Lemsia. Total ascent about 746 m and descent about 1,238 m; the highest point is about 2,455 m above sea level. Along the way: Iverian Virgin Mary Church, Mentashi, Heshkili, Heshkili St. Elijah''s Church, Kashveti.',
  'მარშრუტის სიგრძეა 17.6 კმ. ჯამური აღმართი — დაახლოებით 746 მ, დაღმართი — დაახლოებით 1238 მ, უმაღლესი წერტილი — დაახლოებით 2455 მ ზღვის დონიდან.',
