-- Arkhotistavi Pass Trail (OSM relation 10485719)
INSERT INTO trails (id, name_en, name_ka, description_en, description_ka, difficulty, region, distance_km, elevation_gain_m, estimated_hours, start_address, elevation_profile, review_flags, route, start_point, end_point, is_published) VALUES (
  '3c9818ce-65a9-5a95-81ee-bdcf15216586', 'Arkhotistavi Pass Trail', NULL,
  'A 21.7 km route from Akhieli to Juta. Total ascent about 1,493 m and descent about 1,055 m; the highest point is about 3,280 m above sea level. Along the way: Arkhotistavi Tourist Shelter, Arkhotistavi pass.',
  'მარშრუტის სიგრძეა 21.7 კმ. ჯამური აღმართი — დაახლოებით 1493 მ, დაღმართი — დაახლოებით 1055 მ, უმაღლესი წერტილი — დაახლოებით 3280 მ ზღვის დონიდან.',
