-- Main Ridge Trail (OSM relation 10495654)
INSERT INTO trails (id, name_en, name_ka, description_en, description_ka, difficulty, region, distance_km, elevation_gain_m, estimated_hours, start_address, elevation_profile, review_flags, route, start_point, end_point, is_published) VALUES (
  'bfd9ec3d-b8af-5444-b234-827db31402df', 'Main Ridge Trail', NULL,
  'A 27.9 km route. Total ascent about 1,539 m and descent about 1,281 m; the highest point is about 3,143 m above sea level. Along the way: Datvis-Jvaris-Ghele Pass, Mount Lura, Aknekhi, Tanie Upper Tourist Shelter, Arkhoti, Baghavachosghele.',
  'მარშრუტის სიგრძეა 27.9 კმ. ჯამური აღმართი — დაახლოებით 1539 მ, დაღმართი — დაახლოებით 1281 მ, უმაღლესი წერტილი — დაახლოებით 3143 მ ზღვის დონიდან.',
