-- Likheti - Shkedi (OSM relation 15412745)
INSERT INTO trails (id, name_en, name_ka, description_en, description_ka, difficulty, region, distance_km, elevation_gain_m, estimated_hours, start_address, elevation_profile, review_flags, route, start_point, end_point, is_published) VALUES (
  '9aaa45ae-b30f-54b3-b6d6-5c0690527faa', 'Likheti - Shkedi', 'ლიხეთი - შკედი',
  'A 32.1 km route. Total ascent about 2,473 m and descent about 1,910 m; the highest point is about 3,026 m above sea level. Along the way: Ruins of Mechvreti Monastery, Kelida, Tchutkharo Lakes.',
  'მარშრუტის სიგრძეა 32.1 კმ. ჯამური აღმართი — დაახლოებით 2473 მ, დაღმართი — დაახლოებით 1910 მ, უმაღლესი წერტილი — დაახლოებით 3026 მ ზღვის დონიდან.',
